  { key: 'content', icon: '🎮', title: '주요 콘텐츠', description: '채광부터 도감·파쿠르·미니게임까지' },
  { key: 'growth', icon: '📈', title: '성장 · 경제', description: '땅, 빚, 신용등급, 장비 성장과 FAQ' }
] as const

function mediaIdentity(value: string) {
  const filename = value.split('/').pop() || value
  return filename.replace(/\.[a-z0-9]+$/i, '')
}

function isCardThumbnail(value?: string | null): value is string {
  return Boolean(value && (/\/optimized\/thumb256\//.test(value) || /\/optimized\/thumb\//.test(value)))
}

function assignUniqueMedia(pages: NotionIndexPage[]) {
  const used = new Set<string>()
  const mediaById = new Map<string, string | null>()
  for (const page of pages) {
    const derivedSmall = deriveOptimizedVariant(page.thumbnail, 'thumb256')
    const candidates = [
      page.thumbnailSmall,
      derivedSmall,
      page.thumbnail
    ].filter(isCardThumbnail)
    const media = candidates.find((value) => !used.has(mediaIdentity(value))) ?? null
    if (media) used.add(mediaIdentity(media))
    mediaById.set(page.pageId, media)
  }
  return mediaById
}

export function WikiDirectory({ pages }: { pages: NotionIndexPage[] }) {
  if (!pages.length) return null
  const mediaById = assignUniqueMedia(pages)
  const grouped = GROUPS.map((group) => ({
    ...group,
    pages: pages.filter((page) => categoryForTitle(page.title) === group.key)
  })).filter((group) => group.pages.length > 0)

  return (
    <section className="wiki-directory" aria-labelledby="wiki-directory-title">
      <div className="directory-heading">
        <div>
          <p>QUICK DIRECTORY</p>
          <h2 id="wiki-directory-title">위키 가이드 바로가기</h2>
          <span>이미지와 아이콘만 봐도 문서를 빠르게 구분할 수 있게 정리했습니다.</span>
        </div>
        <span>{pages.length}개 세부 문서</span>
      </div>

      <div className="directory-groups">
        {grouped.map((group) => (
          <section className="directory-group" data-category={group.key} key={group.key}>
            <div className="directory-group-head">
              <span>{group.icon}</span>
              <div>
                <strong>{group.title}</strong>
                <small>{group.description}</small>
              </div>
              <em>{group.pages.length}</em>
            </div>

            <div className="directory-grid">
              {group.pages.map((page) => {
                const media = mediaById.get(page.pageId) ?? null
                const resolvedMedia = media ? resolveCachedAsset(media) : null
                const draft = isDraftPage(page)
                const badge = draft ? '작성 중' : badgeForTitle(page.title)
                const featured = FEATURED.has(page.title) && !draft

                return (
                  <a
                    key={page.pageId}
                    href={withBasePath(`/page/${page.pageId}/`)}
                    className={`directory-card ${featured ? 'is-featured' : ''} ${draft ? 'is-draft' : ''}`}
                    data-status={draft ? 'draft' : 'ready'}
                  >
                    <span className={`directory-media ${media ? 'has-image' : 'is-icon'}`}>
                      {resolvedMedia ? (
                        <img src={resolvedMedia} alt="" aria-hidden="true" loading="lazy" decoding="async" width="256" height="256" />
                      ) : (
                        iconForTitle(page.title)
                      )}
                    </span>

                    <span className="directory-copy">
                      <span className="directory-title-row">
                        <strong>{page.title}</strong>
                        {badge && <em>{badge}</em>}
                      </span>
                      <small>
                        {draft
                          ? '내용을 정리하고 있습니다.'
                          : DESCRIPTION_BY_TITLE[page.title] ||
                            (featured
                              ? '처음이라면 꼭 확인하세요'
                              : '상세 가이드 열기')}
                      </small>
                    </span>

                    <span className="directory-arrow">↗</span>
                  </a>
                )
              })}
            </div>
          </section>
        ))}
      </div>
    </section>
  )
}

import type { NotionIndexPage } from '@/lib/notion-index'
import { withBasePath } from '@/lib/url-utils'

function categoryTitle(title: string) {
  const value = title.toLowerCase()

  if (
    value.includes('스토리') ||
    value.includes('규칙') ||
    value.includes('패치') ||
    value.includes('api') ||
    value.includes('뉴비') ||
    value.includes('기초')
  ) {
    return '시작하기'
  }

  if (
    value.includes('땅') ||
    value.includes('빚') ||
    value.includes('신용') ||
    value.includes('수리') ||
    value.includes('강화') ||
    value.includes('물어보는')
  ) {
    return '성장 · 경제'
  }

  return '주요 콘텐츠'
}

function formatDate(value: string | null) {
  if (!value) return null
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return null
  return new Intl.DateTimeFormat('ko-KR', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(date)
}

export function WikiPageNavigation({
  current,
  pages,
  mode = 'context'
}: {
  current: NotionIndexPage | null
  pages: NotionIndexPage[]
  mode?: 'context' | 'siblings'
}) {
  if (!current) return null

  const currentIndex = pages.findIndex((page) => page.pageId === current.pageId)
  const previous = currentIndex > 0 ? pages[currentIndex - 1] : null
  const next =
    currentIndex >= 0 && currentIndex < pages.length - 1
      ? pages[currentIndex + 1]
      : null
  const category = categoryTitle(current.title)
  const updatedAt = formatDate(current.lastEdited)

  if (mode === 'siblings') {
    return (
      <nav className="page-siblings page-siblings-bottom" aria-label="이전 및 다음 문서">
        {previous ? (
          <a href={withBasePath(`/page/${previous.pageId}/`)}>
            <small>← 이전 문서</small>
            <strong>{previous.title}</strong>
          </a>
        ) : (
          <span />
        )}

        {next ? (
          <a
            href={withBasePath(`/page/${next.pageId}/`)}
            className="page-sibling-next"
          >
            <small>다음 문서 →</small>
            <strong>{next.title}</strong>
          </a>
        ) : (
          <span />
        )}
      </nav>
    )
  }

  return (
    <div className="page-context">
      <nav className="breadcrumbs" aria-label="현재 위치">
        <a href={withBasePath('/')}>위키 홈</a>
        <span>›</span>
        <span>{category}</span>
        <span>›</span>
        <strong>{current.title}</strong>
      </nav>
      {updatedAt && <span className="page-updated">최근 수정 {updatedAt}</span>}
    </div>
  )
}

'use client'

import { useEffect, useMemo, useRef, useState } from 'react'

import { withBasePath } from '@/lib/url-utils'

type TocItem = {
  id: string
  text: string
  level: number
}

type WikiPageLink = {
  pageId: string
  title: string
}

type SearchPage = WikiPageLink & {
  searchText?: string
}

const SEARCH_INDEX_URL = withBasePath(
  '/api/notion-webhook?resource=search-index'
)

function sectionIcon(text: string) {
  const value = text.toLowerCase()

  if (value.includes('스토리')) return '📖'
  if (value.includes('규칙') || value.includes('룰')) return '📜'
  if (value.includes('api') || value.includes('후원')) return '💝'
  if (value.includes('뉴비') || value.includes('기초')) return '🧭'
  if (value.includes('패치') || value.includes('업데이트')) return '📝'
  if (value.includes('강화')) return '⚒️'
  if (value.includes('수리')) return '🔧'
  if (value.includes('광산') || value.includes('채광')) return '⛏️'
  if (value.includes('낚시')) return '🎣'
  if (value.includes('도축')) return '🥩'
  if (value.includes('사냥')) return '⚔️'
  if (value.includes('요리')) return '🍳'
  if (value.includes('도감')) return '📚'
  if (value.includes('파쿠르')) return '🏃'
  if (value.includes('복권')) return '🎟️'
  if (value.includes('경마')) return '🏇'
  if (value.includes('카지노') || value.includes('가챠')) return '🎰'
  if (value.includes('땅')) return '🏠'
  if (value.includes('빚')) return '💸'
  if (value.includes('신용')) return '💳'
  if (value.includes('물어보는')) return '❓'
  if (value.includes('참여') || value.includes('접속')) return '📢'
  if (value.includes('아이템')) return '🎁'
  if (value.includes('안내') || value.includes('가이드')) return '🧭'

  return '✦'
}

function categoryLabel(title: string) {
  const value = title.toLowerCase()

  if (
    value.includes('스토리') ||
    value.includes('규칙') ||
    value.includes('패치') ||
    value.includes('api') ||
    value.includes('뉴비') ||
    value.includes('기초')
  ) {
    return '시작하기'
  }

  if (
    value.includes('땅') ||
    value.includes('빚') ||
    value.includes('신용') ||
    value.includes('수리') ||
    value.includes('강화') ||
    value.includes('물어보는')
  ) {
    return '성장 · 경제'
  }

  return '주요 콘텐츠'
}

function HighlightedText({
  text,
  query
}: {
  text: string
  query: string
}) {
  const keyword = query.trim()
  if (!keyword) return <>{text}</>

  const lower = text.toLowerCase()
  const index = lower.indexOf(keyword.toLowerCase())
  if (index < 0) return <>{text}</>

  return (
    <>
      {text.slice(0, index)}
      <mark>{text.slice(index, index + keyword.length)}</mark>
      {text.slice(index + keyword.length)}
    </>
  )
}

export function WikiShell({
  children,
  sourceUrl,
  title,
  pageCount,
  pages,
  brandLogo,
  heroImage,
  heroImageMd,
  heroImageSm,
  currentPageId,
  home = false
}: {
  children: React.ReactNode
  sourceUrl: string
  title: string
  pageCount: number
  pages: WikiPageLink[]
  brandLogo?: string | null
  heroImage?: string | null
  heroImageMd?: string | null
  heroImageSm?: string | null
  currentPageId?: string | null
  home?: boolean
}) {
  const [toc, setToc] = useState<TocItem[]>([])
  const [query, setQuery] = useState('')
  const [menuOpen, setMenuOpen] = useState(false)
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false)
  const [searchOpen, setSearchOpen] = useState(false)
  const [theme, setTheme] = useState<'dark' | 'light'>('dark')
  const [activeTocId, setActiveTocId] = useState('')
  const [readingProgress, setReadingProgress] = useState(0)
  const [searchPages, setSearchPages] = useState<SearchPage[] | null>(null)
  const [searchLoading, setSearchLoading] = useState(false)
  const [searchFailed, setSearchFailed] = useState(false)
  const [selectedResult, setSelectedResult] = useState(0)
  const modalSearchRef = useRef<HTMLInputElement>(null)
  const modalRef = useRef<HTMLElement>(null)

  useEffect(() => {
    const saved = window.localStorage.getItem('justserver3-theme')
    const nextTheme =
      saved === 'light' || saved === 'dark'
        ? saved
        : window.matchMedia('(prefers-color-scheme: light)').matches
          ? 'light'
          : 'dark'

    setTheme(nextTheme)
    document.documentElement.dataset.theme = nextTheme
  }, [])

  useEffect(() => {
    document.documentElement.dataset.theme = theme
    window.localStorage.setItem('justserver3-theme', theme)
  }, [theme])

  useEffect(() => {
    const saved = window.localStorage.getItem('justserver3-sidebar-collapsed')
    const collapsed = saved === 'true'
    setSidebarCollapsed(collapsed)
    document.documentElement.dataset.sidebar = collapsed
      ? 'collapsed'
      : 'expanded'
  }, [])

  const toggleSidebar = () => {
    setSidebarCollapsed((value) => {
      const next = !value
      window.localStorage.setItem(
        'justserver3-sidebar-collapsed',
        String(next)
      )
      document.documentElement.dataset.sidebar = next
        ? 'collapsed'
        : 'expanded'
      return next
    })
  }

  useEffect(() => {
    const timer = window.setTimeout(() => {
      const nodes = Array.from(
        document.querySelectorAll<HTMLElement>(
          '.notion-page-content h1, .notion-page-content h2, .notion-page-content h3'
        )
      )

      const next = nodes
        .map((node, index) => {
          const text = node.textContent?.trim() ?? ''
          if (!text) return null
          if (!node.id) node.id = `section-${index + 1}`
          const level = Number(node.tagName.slice(1))
          return { id: node.id, text, level }
        })
        .filter((item): item is TocItem => Boolean(item))

      setToc(next)
    }, 450)

    return () => window.clearTimeout(timer)
  }, [children])

  useEffect(() => {
    if (!toc.length) {
      setActiveTocId('')
      return
    }

    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((entry) => entry.isIntersecting)
          .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top)

        if (visible[0]?.target.id) {
          setActiveTocId(visible[0].target.id)
        }
      },
      {
        rootMargin: '-18% 0px -68% 0px',
        threshold: [0, 1]
      }
    )

    for (const item of toc) {
      const element = document.getElementById(item.id)
      if (element) observer.observe(element)
    }

    return () => observer.disconnect()
  }, [toc])

  useEffect(() => {
    if (home) return

    let frame = 0

    const updateProgress = () => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(() => {
        const article = document.querySelector<HTMLElement>('.document-card')
        if (!article) return

        const rect = article.getBoundingClientRect()
        const start = window.scrollY + rect.top - 120
        const end =
          start +
          Math.max(article.offsetHeight - window.innerHeight * 0.42, 1)
        const value = Math.min(
          1,
          Math.max(0, (window.scrollY - start) / Math.max(end - start, 1))
        )

        setReadingProgress(Math.round(value * 100))
      })
    }

    updateProgress()
    window.addEventListener('scroll', updateProgress, { passive: true })
    window.addEventListener('resize', updateProgress)

    return () => {
      cancelAnimationFrame(frame)
      window.removeEventListener('scroll', updateProgress)
      window.removeEventListener('resize', updateProgress)
    }
  }, [home])

  const openSearch = () => {
    setSearchOpen(true)
    window.setTimeout(() => modalSearchRef.current?.focus(), 30)
  }

  useEffect(() => {
    if (!searchOpen || searchPages || searchLoading) return

    let cancelled = false

    const load = async () => {
      setSearchLoading(true)
      setSearchFailed(false)

      try {
        const response = await fetch(SEARCH_INDEX_URL)
        if (!response.ok) throw new Error(`HTTP ${response.status}`)

        const data = (await response.json()) as {
          pages?: SearchPage[]
        }

        if (!cancelled) {
          setSearchPages(Array.isArray(data.pages) ? data.pages : [])
        }
      } catch {
        if (!cancelled) setSearchFailed(true)
      } finally {
        if (!cancelled) setSearchLoading(false)
      }
    }

    void load()

    return () => {
      cancelled = true
    }
  }, [searchOpen, searchPages, searchLoading])

  const filteredPages = useMemo(() => {
    const source: SearchPage[] =
      searchPages ?? pages.map((page) => ({ ...page, searchText: '' }))
    const keyword = query.trim().toLowerCase()

    if (!keyword) {
      return source.slice(0, 10).map((page) => ({ ...page, snippet: '' }))
    }

    return source
      .map((page) => {
        const title = page.title.toLowerCase()
        const searchText = page.searchText ?? ''
        const body = searchText.toLowerCase()
        const titleMatch = title.includes(keyword)
        const bodyIndex = body.indexOf(keyword)

        if (!titleMatch && bodyIndex < 0) return null

        let snippet = ''
        if (bodyIndex >= 0 && searchText) {
          const start = Math.max(0, bodyIndex - 56)
          const end = Math.min(
            searchText.length,
            bodyIndex + keyword.length + 88
          )
          snippet = `${start > 0 ? '…' : ''}${searchText
            .slice(start, end)
            .trim()}${end < searchText.length ? '…' : ''}`
        }

        return { ...page, snippet }
      })
      .filter(
        (
          page
        ): page is SearchPage & {
          snippet: string
        } => Boolean(page)
      )
      .slice(0, 14)
  }, [pages, query, searchPages])

  useEffect(() => {
    setSelectedResult(0)
  }, [query, filteredPages.length])

  useEffect(() => {
    if (!searchOpen) return

    const previousOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'ArrowDown') {
        event.preventDefault()
        setSelectedResult((value) =>
          filteredPages.length ? (value + 1) % filteredPages.length : 0
        )
      }

      if (event.key === 'ArrowUp') {
        event.preventDefault()
        setSelectedResult((value) =>
          filteredPages.length
            ? (value - 1 + filteredPages.length) % filteredPages.length
            : 0
        )
      }

      if (event.key === 'Enter' && filteredPages[selectedResult]) {
        event.preventDefault()
        window.location.assign(
          withBasePath(`/page/${filteredPages[selectedResult].pageId}/`)
        )
      }

      if (event.key === 'Tab' && modalRef.current) {
        const focusable = Array.from(
          modalRef.current.querySelectorAll<HTMLElement>(
            'input, button, a[href], [tabindex]:not([tabindex="-1"])'
          )
        ).filter((element) => !element.hasAttribute('disabled'))

        if (!focusable.length) return
        const first = focusable[0]
        const last = focusable[focusable.length - 1]

        if (event.shiftKey && document.activeElement === first) {
          event.preventDefault()
          last.focus()
        } else if (!event.shiftKey && document.activeElement === last) {
          event.preventDefault()
          first.focus()
        }
      }
    }

    window.addEventListener('keydown', onKeyDown)

    return () => {
      document.body.style.overflow = previousOverflow
      window.removeEventListener('keydown', onKeyDown)
    }
  }, [filteredPages, searchOpen, selectedResult])

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement | null
      const isTyping =
        target?.tagName === 'INPUT' ||
        target?.tagName === 'TEXTAREA' ||
        target?.isContentEditable

      if (
        (event.key === '/' && !isTyping) ||
        ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k')
      ) {
        event.preventDefault()
        openSearch()
      }

      if (event.key === 'Escape') {
        setSearchOpen(false)
        setQuery('')
        modalSearchRef.current?.blur()
      }
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [])

  const goTo = (id: string) => {
    document.getElementById(id)?.scrollIntoView({
      behavior: 'smooth',
      block: 'start'
    })
    setMenuOpen(false)
  }

  return (
    <div className={`wiki-shell ${sidebarCollapsed ? 'is-sidebar-collapsed' : ''}`}>
      <a className="skip-link" href="#main-content">
        본문으로 건너뛰기
      </a>

      <header className="wiki-topbar">
        <button
          className="menu-button"
          type="button"
          aria-label="메뉴 열기"
          onClick={() => setMenuOpen((value) => !value)}
        >
          ☰
        </button>

        <a className="brand" href={withBasePath('/')}>
          <span className="brand-mark brand-image-mark">
            {brandLogo ? (
              <img
                className="brand-logo-image"
                src={brandLogo}
                alt=""
                aria-hidden="true"
                width="54"
                height="54"
                decoding="async"
              />
            ) : (
              <span>적</span>
            )}
          </span>
          <span>
            <strong>{home ? '그냥서버 : 적자생존' : title}</strong>
            <small>OFFICIAL WIKI</small>
          </span>
        </a>

        <div className="top-actions">
          <button
            className="header-search-button"
            type="button"
            aria-keyshortcuts="Control+K Meta+K /"
            onClick={openSearch}
          >
            <span>⌕</span>
            <span>문서 검색</span>
            <kbd>Ctrl K</kbd>
          </button>

          <button
            className="theme-toggle"
            type="button"
            aria-pressed={theme === 'light'}
            aria-label={
              theme === 'dark' ? '라이트 모드로 전환' : '다크 모드로 전환'
            }
            onClick={() =>
              setTheme((value) => (value === 'dark' ? 'light' : 'dark'))
            }
          >
            {theme === 'dark' ? '☀' : '☾'}
          </button>

        </div>
      </header>

      <aside className={`wiki-sidebar ${menuOpen ? 'is-open' : ''}`}>
        <div className="sidebar-head">
          <strong>문서 탐색</strong>
          <span>{pages.length}개</span>
        </div>

        {!home && (
          <button
            className="wiki-search wiki-search-trigger"
            type="button"
            aria-keyshortcuts="Control+K Meta+K /"
            onClick={openSearch}
          >
            <span>⌕</span>
            <span>전체 문서 검색</span>
            <kbd>⌘K</kbd>
          </button>
        )}

        <div className="sidebar-primary-links">
          <a className="sidebar-home" href={withBasePath('/')}>
            <span>🏠</span>
            위키 홈
          </a>
        </div>

        <nav className="toc-list">
          <div className="global-page-list">
            <span className="nav-section-label">전체 문서</span>
            {['시작하기', '주요 콘텐츠', '성장 · 경제'].map((group) => {
              const groupPages = pages.filter(
                (page) => categoryLabel(page.title) === group
              )

              if (!groupPages.length) return null

              return (
                <section className="sidebar-category" key={group}>
                  <div className="sidebar-category-head">
                    <strong>{group}</strong>
                    <span>{groupPages.length}</span>
                  </div>
                  <div className="sidebar-category-links">
                    {groupPages.map((page) => (
                      <a
                        key={page.pageId}
                        href={withBasePath(`/page/${page.pageId}/`)}
                        className={`global-page-link ${
                          currentPageId &&
                          page.pageId.replaceAll('-', '') ===
                            currentPageId.replaceAll('-', '')
                            ? 'is-current'
                            : ''
                        }`}
                        aria-current={
                          currentPageId &&
                          page.pageId.replaceAll('-', '') ===
                            currentPageId.replaceAll('-', '')
                            ? 'page'
                            : undefined
                        }
                      >
                        <span className="sidebar-page-icon" aria-hidden="true">
                          {sectionIcon(page.title)}
                        </span>
                        <span className="global-page-copy">
                          <strong>{page.title}</strong>
                        </span>
                      </a>
                    ))}
                  </div>
                </section>
              )
            })}
          </div>

          <div className="current-toc mobile-current-toc">
            <span className="nav-section-label">현재 페이지</span>
            {toc.length ? (
              toc.map((item) => (
                <button
                  key={item.id}
                  type="button"
                  className={`toc-item level-${item.level} ${
                    activeTocId === item.id ? 'is-active' : ''
                  }`}
                  aria-current={activeTocId === item.id ? 'location' : undefined}
                  onClick={() => goTo(item.id)}
                >
                  <span>{sectionIcon(item.text)}</span>
                  <span>{item.text}</span>
                </button>
              ))
            ) : (
              <p className="toc-empty">현재 페이지 목차가 없습니다.</p>
            )}
          </div>
        </nav>

        <div className="sidebar-foot">
          <span className="live-dot" />
          공식 가이드 문서
        </div>
      </aside>

      <button
        className="sidebar-edge-toggle"
        type="button"
        aria-label={sidebarCollapsed ? '문서 목록 펼치기' : '문서 목록 접기'}
        aria-pressed={sidebarCollapsed}
        title={sidebarCollapsed ? '문서 목록 펼치기' : '문서 목록 접기'}
        onClick={toggleSidebar}
      >
        <span className="sidebar-toggle-expanded" aria-hidden="true">‹</span>
        <span className="sidebar-toggle-collapsed" aria-hidden="true">
          <b>☰</b><em>문서</em>
        </span>
      </button>

      {menuOpen && (
        <button
          className="sidebar-backdrop"
          type="button"
          aria-label="메뉴 닫기"
          onClick={() => setMenuOpen(false)}
        />
      )}

      {!home && toc.length > 0 && (
        <aside className="article-toc" aria-label="현재 문서 목차">
          <div className="article-progress">
            <span>읽는 중</span>
            <strong>{readingProgress}%</strong>
          </div>
          <div className="article-progress-track" aria-hidden="true">
            <span style={{ height: `${readingProgress}%` }} />
          </div>
          <span className="article-toc-label">이 페이지에서</span>
          <nav>
            {toc.map((item) => (
              <button
                key={item.id}
                type="button"
                className={`article-toc-item level-${item.level} ${
                  activeTocId === item.id ? 'is-active' : ''
                }`}
                aria-current={activeTocId === item.id ? 'location' : undefined}
                onClick={() => goTo(item.id)}
              >
                {item.text}
              </button>
            ))}
          </nav>
        </aside>
      )}

      <main
        className={`wiki-main ${!home && toc.length ? 'has-article-toc' : ''}`}
        id="main-content"
      >
        <section
          className={`wiki-hero ${home ? 'is-home' : 'is-article'} ${heroImage ? 'has-hero-image' : ''}`}
          aria-label="위키 안내"
        >
          {heroImage && home && (
            <picture className="hero-background-image" aria-hidden="true">
              {heroImageSm && (
                <source media="(max-width: 640px)" srcSet={heroImageSm} />
              )}
              {heroImageMd && (
                <source media="(max-width: 1280px)" srcSet={heroImageMd} />
              )}
              <img
                src={heroImage}
                alt=""
                width="1600"
                height="900"
                loading="eager"
                fetchPriority="high"
                decoding="async"
              />
            </picture>
          )}
          <div className="hero-overlay" aria-hidden="true" />

          {home && (
            <div className="hero-badges">
              <span className="hero-badge primary">공식 위키</span>
              <span className="hero-badge">🧭 뉴비 필독</span>
              <span className="hero-badge">📚 문서 {pageCount}개</span>
            </div>
          )}

          <div className="hero-copy">
            <p className="hero-kicker">
              {home ? 'JUST SERVER · SURVIVAL WIKI' : 'WIKI DOCUMENT'}
            </p>
            <h1>{title}</h1>
            {home && (
              <p>
                서버 규칙부터 돈벌이, 콘텐츠, 장비 성장까지 적자생존에 필요한 정보를 한곳에서 빠르게 찾아보세요.
              </p>
            )}
            {home && (
              <button
                className="hero-search-cta"
                type="button"
                aria-keyshortcuts="Control+K Meta+K /"
                onClick={openSearch}
              >
                <span>⌕</span>
                <span>가이드, 콘텐츠, 아이템을 검색하세요</span>
                <kbd>Ctrl K</kbd>
              </button>
            )}
          </div>
        </section>

        {children}

        <footer className="wiki-footer">
          <div>
            <strong>{home ? '그냥서버 : 적자생존 공식 위키' : title}</strong>
            <span>서버 규칙과 플레이 가이드를 한곳에서 확인하세요.</span>
          </div>
          <nav className="footer-links">
            <a href={sourceUrl} target="_blank" rel="noreferrer">
              원본 문서 ↗
            </a>
          </nav>
        </footer>
      </main>

      {searchOpen && (
        <div
          className="search-modal-backdrop"
          role="presentation"
          onMouseDown={(event) => {
            if (event.currentTarget === event.target) setSearchOpen(false)
          }}
        >
          <section
            ref={modalRef}
            className="search-modal"
            role="dialog"
            aria-modal="true"
            aria-label="위키 전체 검색"
          >
            <div className="search-modal-input" role="search">
              <span>⌕</span>
              <input
                ref={modalSearchRef}
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                placeholder="규칙, 빚, 채광, 강화 등 무엇이든 검색하세요"
                aria-label="위키 전체 검색"
                aria-controls="wiki-search-results"
              />
              <button
                type="button"
                aria-label="검색 닫기"
                onClick={() => setSearchOpen(false)}
              >
                ESC
              </button>
            </div>

            <div className="search-result-meta" aria-live="polite">
              {searchLoading
                ? '본문 검색 색인을 불러오는 중…'
                : searchFailed
                  ? '본문 색인을 불러오지 못해 제목 검색으로 표시합니다.'
                  : query.trim()
                    ? `${filteredPages.length}개의 검색 결과`
                    : '추천 문서 · ↑↓ 선택 · Enter 이동'}
            </div>

            <div
              className="search-modal-results"
              id="wiki-search-results"
              role="listbox"
              aria-label="검색 결과"
            >
              {filteredPages.length ? (
                filteredPages.map((page, index) => (
                  <a
                    key={page.pageId}
                    href={withBasePath(`/page/${page.pageId}/`)}
                    className={`search-result-card ${
                      selectedResult === index ? 'is-selected' : ''
                    }`}
                    data-category={categoryLabel(page.title)}
                    role="option"
                    aria-selected={selectedResult === index}
                    onMouseEnter={() => setSelectedResult(index)}
                  >
                    <span className="search-result-icon">
                      {sectionIcon(page.title)}
                    </span>
                    <span>
                      <span className="search-result-category">
                        {categoryLabel(page.title)}
                      </span>
                      <strong>
                        <HighlightedText text={page.title} query={query} />
                      </strong>
                      <small>
                        {page.snippet ? (
                          <HighlightedText text={page.snippet} query={query} />
                        ) : (
                          '상세 가이드 열기'
                        )}
                      </small>
                    </span>
                    <b>↗</b>
                  </a>
                ))
              ) : (
                <p className="search-empty">
                  일치하는 문서가 없습니다. 다른 검색어를 입력해보세요.
                </p>
              )}
            </div>
          </section>
        </div>
      )}
    </div>
  )
}

import type { NotionIndexPage } from '@/lib/notion-index'

const PLACEHOLDER_PATTERN = /위키\s*업데이트\s*예정|내용\s*추가\s*예정|작성\s*중/i

export function isDraftPage(page: Pick<NotionIndexPage, 'searchText'>) {
  const text = (page.searchText || '').replace(/\s+/g, ' ').trim()
  return PLACEHOLDER_PATTERN.test(text) || text.length < 80
}
